package com.spai.portal.task.domain;
import javax.persistence.*;
@Entity @Table(name="delivery_task") public class DeliveryTask {@Id private String id;@Column(name="external_id",nullable=false,unique=true)private String externalId;@Column(nullable=false)private String stage;@Column(nullable=false)private String scene;@Column(nullable=false,length=1000)private String ai;@Column(nullable=false,length=2000)private String description;@Column(name="input_text",length=2000)private String input;@Column(name="output_text",length=1000)private String output;@Column(name="carrier_type",nullable=false)private String type;@Column(name="skill_name",nullable=false)private String skill;@Column(nullable=false)private String priority;@Column(nullable=false)private String difficulty;@Column(nullable=false)private boolean enabled=true;public String getId(){return id;}public void setId(String id){this.id=id;}public String getExternalId(){return externalId;}public void setExternalId(String externalId){this.externalId=externalId;}public String getStage(){return stage;}public void setStage(String stage){this.stage=stage;}public String getScene(){return scene;}public void setScene(String scene){this.scene=scene;}public String getAi(){return ai;}public void setAi(String ai){this.ai=ai;}public String getDescription(){return description;}public void setDescription(String description){this.description=description;}public String getInput(){return input;}public void setInput(String input){this.input=input;}public String getOutput(){return output;}public void setOutput(String output){this.output=output;}public String getType(){return type;}public void setType(String type){this.type=type;}public String getSkill(){return skill;}public void setSkill(String skill){this.skill=skill;}public String getPriority(){return priority;}public void setPriority(String priority){this.priority=priority;}public String getDifficulty(){return difficulty;}public void setDifficulty(String difficulty){this.difficulty=difficulty;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean enabled){this.enabled=enabled;}}
